/**
 * Span and trace data types and tree-building utilities.
 */

import type { TraceFieldMapping } from "./traceQueryBuilder";

/** A single event recorded within a span */
export interface SpanEvent {
  name: string;
  timestamp: string;
  attributes: Record<string, unknown>;
}

/** Represents a link from a span to another span/trace */
export interface SpanLink {
  traceId: string;
  spanId: string;
  attributes: Record<string, unknown>;
}

/** Represents a single span in a trace */
export interface Span {
  traceId: string;
  spanId: string;
  parentSpanId: string | null;
  serviceName: string;
  name: string;
  kind: string;
  durationUs: number;
  status: string;
  timestamp: string;
  startTimeUs: number;
  attributes: Record<string, unknown>;
  events?: SpanEvent[];
  links?: SpanLink[];
}

/** A span augmented with tree information for rendering */
export interface SpanTreeNode {
  span: Span;
  children: SpanTreeNode[];
  depth: number;
}

export interface ServiceMapNode {
  serviceName: string;
  spanCount: number;
  errorCount: number;
}

export interface ServiceMapEdge {
  source: string;
  target: string;
  callCount: number;
  errorCount: number;
  totalDurationUs: number;
}

export interface ServiceMapData {
  nodes: ServiceMapNode[];
  edges: ServiceMapEdge[];
}

/**
 * Build a span tree from a flat list of spans.
 * Returns root nodes (spans with no parent or whose parent is not in the list).
 * Handles orphan spans by attaching them as roots.
 * Detects and breaks cycles by tracking visited spans.
 */
export function buildSpanTree(spans: Span[]): SpanTreeNode[] {
  const byId = new Map<string, SpanTreeNode>();
  for (const span of spans) {
    byId.set(span.spanId, { span, children: [], depth: 0 });
  }

  const roots: SpanTreeNode[] = [];

  for (const node of byId.values()) {
    const parentId = node.span.parentSpanId;
    if (parentId && byId.has(parentId)) {
      byId.get(parentId)!.children.push(node);
    } else {
      roots.push(node);
    }
  }

  // If every span points to a parent present in this trace (pure cycle),
  // seed a deterministic synthetic root so rendering doesn't collapse to empty.
  if (roots.length === 0 && byId.size > 0) {
    let earliestNode: SpanTreeNode | null = null;
    for (const node of byId.values()) {
      if (!earliestNode || node.span.startTimeUs < earliestNode.span.startTimeUs) {
        earliestNode = node;
      }
    }
    if (earliestNode) {
      roots.push(earliestNode);
    }
  }

  // Sort children by timestamp (chronological order)
  const sortedVisited = new Set<string>();
  function sortChildren(node: SpanTreeNode): void {
    if (sortedVisited.has(node.span.spanId)) return;
    sortedVisited.add(node.span.spanId);
    node.children.sort((a, b) => a.span.startTimeUs - b.span.startTimeUs);
    for (const child of node.children) {
      sortChildren(child);
    }
  }

  // Sort roots by timestamp
  roots.sort((a, b) => a.span.startTimeUs - b.span.startTimeUs);

  for (const root of roots) {
    sortChildren(root);
  }

  // Assign depths via DFS, breaking cycles
  const visited = new Set<string>();
  function assignDepths(node: SpanTreeNode, depth: number): void {
    if (visited.has(node.span.spanId)) return;
    visited.add(node.span.spanId);
    node.depth = depth;
    for (const child of node.children) {
      assignDepths(child, depth + 1);
    }
  }

  for (const root of roots) {
    assignDepths(root, 0);
  }

  // Promote disconnected unvisited components (e.g. mixed root+cycle traces).
  while (true) {
    const unvisitedNodes = Array.from(byId.values()).filter(
      (node) => !visited.has(node.span.spanId),
    );
    if (unvisitedNodes.length === 0) break;

    const unvisitedIds = new Set(unvisitedNodes.map((node) => node.span.spanId));
    const nonLeafCandidates = unvisitedNodes.filter((node) =>
      node.children.some((child) => unvisitedIds.has(child.span.spanId)),
    );
    const candidates = nonLeafCandidates.length > 0 ? nonLeafCandidates : unvisitedNodes;

    let syntheticRoot = candidates[0]!;
    for (const node of candidates) {
      if (
        node.span.startTimeUs < syntheticRoot.span.startTimeUs ||
        (node.span.startTimeUs === syntheticRoot.span.startTimeUs &&
          node.span.spanId < syntheticRoot.span.spanId)
      ) {
        syntheticRoot = node;
      }
    }

    roots.push(syntheticRoot);
    sortChildren(syntheticRoot);
    assignDepths(syntheticRoot, 0);
  }
  roots.sort((a, b) => a.span.startTimeUs - b.span.startTimeUs);

  return roots;
}

/**
 * Flatten a span tree via DFS for waterfall rendering.
 * Returns spans in visual order (parent above children, siblings in chronological order).
 */
export function flattenSpanTree(roots: SpanTreeNode[]): SpanTreeNode[] {
  const result: SpanTreeNode[] = [];
  const visited = new Set<string>();
  function dfs(node: SpanTreeNode): void {
    if (visited.has(node.span.spanId)) return;
    visited.add(node.span.spanId);
    result.push(node);
    for (const child of node.children) {
      dfs(child);
    }
  }
  for (const root of roots) {
    dfs(root);
  }
  return result;
}

export function isErrorStatus(status: string): boolean {
  return status === "Error" || status === "STATUS_CODE_ERROR";
}

/**
 * Build an aggregated service dependency graph from span parent/child links.
 */
export function buildServiceMapData(spans: Span[]): ServiceMapData {
  const spanById = new Map<string, Span>();
  const nodeStats = new Map<string, ServiceMapNode>();
  const edgeStats = new Map<string, ServiceMapEdge>();

  for (const span of spans) {
    spanById.set(span.spanId, span);
    const existingNode = nodeStats.get(span.serviceName);
    if (existingNode) {
      existingNode.spanCount += 1;
      existingNode.errorCount += isErrorStatus(span.status) ? 1 : 0;
    } else {
      nodeStats.set(span.serviceName, {
        serviceName: span.serviceName,
        spanCount: 1,
        errorCount: isErrorStatus(span.status) ? 1 : 0,
      });
    }
  }

  for (const span of spans) {
    if (!span.parentSpanId) continue;
    const parentSpan = spanById.get(span.parentSpanId);
    if (!parentSpan || parentSpan.serviceName === span.serviceName) continue;

    const key = `${parentSpan.serviceName}→${span.serviceName}`;
    const existingEdge = edgeStats.get(key);
    if (existingEdge) {
      existingEdge.callCount += 1;
      existingEdge.errorCount += isErrorStatus(span.status) ? 1 : 0;
      existingEdge.totalDurationUs += span.durationUs;
    } else {
      edgeStats.set(key, {
        source: parentSpan.serviceName,
        target: span.serviceName,
        callCount: 1,
        errorCount: isErrorStatus(span.status) ? 1 : 0,
        totalDurationUs: span.durationUs,
      });
    }
  }

  return {
    nodes: Array.from(nodeStats.values()),
    edges: Array.from(edgeStats.values()),
  };
}

/**
 * Parse raw ES|QL response rows into Span objects.
 * Maps column names to span fields using a flexible lookup.
 */
export function parseSpansFromEsql(
  columns: Array<{ name: string; type: string }>,
  values: unknown[][],
  fieldMapping: Omit<TraceFieldMapping, "index">,
): Span[] {
  const colIndex = new Map<string, number>();
  for (let i = 0; i < columns.length; i++) {
    colIndex.set(columns[i]!.name, i);
  }

  // Gather all known field names to exclude from attributes
  const knownFields = new Set(Object.values(fieldMapping).filter(Boolean));
  const eventsField = fieldMapping.events ?? "events";

  // Precompute attribute columns (columns that end up in the attributes bag)
  const attrColumns: Array<[string, number]> = [];
  for (const [colName, idx] of colIndex) {
    if (!knownFields.has(colName) && colName !== eventsField && !isSpanLinkColumn(colName)) {
      attrColumns.push([colName, idx]);
    }
  }

  // Precompute field indices once instead of per-row Map.get calls
  const traceIdIdx = colIndex.get(fieldMapping.traceId);
  const spanIdIdx = colIndex.get(fieldMapping.spanId);
  const parentSpanIdIdx = colIndex.get(fieldMapping.parentSpanId);
  const serviceNameIdx = colIndex.get(fieldMapping.serviceName);
  const spanNameIdx = colIndex.get(fieldMapping.spanName);
  const spanKindIdx = colIndex.get(fieldMapping.spanKind);
  const durationUsIdx = colIndex.get(fieldMapping.durationUs);
  const durationNsIdx = colIndex.get(fieldMapping.durationNs);
  const statusCodeIdx = colIndex.get(fieldMapping.statusCode);
  const timestampIdx = colIndex.get(fieldMapping.timestamp);
  const timestampUsIdx = colIndex.get(fieldMapping.timestampUs);
  const eventsIdx = colIndex.get(eventsField);

  // Skip link parsing when link columns are absent
  const hasLinkColumns = colIndex.has("links.trace.id") && colIndex.has("links.span.id");

  const spans: Span[] = new Array(values.length);
  for (let rowIndex = 0; rowIndex < values.length; rowIndex++) {
    const row = values[rowIndex]!;

    const attributes: Record<string, unknown> = {};
    for (let a = 0; a < attrColumns.length; a++) {
      const [colName, idx] = attrColumns[a]!;
      if (row[idx] != null) {
        attributes[colName] = row[idx];
      }
    }

    const rawTimestampUs = timestampUsIdx !== undefined ? row[timestampUsIdx] : null;
    const rawDurationUs = durationUsIdx !== undefined ? row[durationUsIdx] : null;
    const rawDurationNs = durationNsIdx !== undefined ? row[durationNsIdx] : null;
    const rawTimestamp = timestampIdx !== undefined ? row[timestampIdx] : null;

    const parsedTimestampUs = Number(rawTimestampUs ?? NaN);
    const parsedDurationUs = Number(rawDurationUs ?? NaN);
    const parsedDurationNs = Number(rawDurationNs ?? NaN);
    const fallbackTimestampUs = new Date(String(rawTimestamp ?? "")).getTime() * 1000;
    const startTimeUsCandidate =
      Number.isFinite(parsedTimestampUs) && parsedTimestampUs > 0
        ? parsedTimestampUs
        : fallbackTimestampUs;
    const startTimeUs = Number.isFinite(startTimeUsCandidate) ? startTimeUsCandidate : 0;
    const durationUs =
      Number.isFinite(parsedDurationUs) && parsedDurationUs > 0
        ? parsedDurationUs
        : Number.isFinite(parsedDurationNs) && parsedDurationNs > 0
          ? parsedDurationNs / 1000
          : 0;

    const rawParentSpanId = parentSpanIdIdx !== undefined ? row[parentSpanIdIdx] : null;

    spans[rowIndex] = {
      traceId: String((traceIdIdx !== undefined ? row[traceIdIdx] : null) ?? ""),
      spanId: String((spanIdIdx !== undefined ? row[spanIdIdx] : null) ?? ""),
      parentSpanId: rawParentSpanId ? String(rawParentSpanId) : null,
      serviceName: String((serviceNameIdx !== undefined ? row[serviceNameIdx] : null) ?? "unknown"),
      name: String((spanNameIdx !== undefined ? row[spanNameIdx] : null) ?? ""),
      kind: String((spanKindIdx !== undefined ? row[spanKindIdx] : null) ?? ""),
      durationUs,
      status: String((statusCodeIdx !== undefined ? row[statusCodeIdx] : null) ?? "OK"),
      timestamp: String(rawTimestamp ?? ""),
      startTimeUs,
      attributes,
      events: parseSpanEvents(eventsIdx !== undefined ? row[eventsIdx] : null),
      links: hasLinkColumns ? parseSpanLinks(colIndex, row) : [],
    };
  }
  return spans;
}

/** Parse a raw events column value into an array of SpanEvent objects */
function parseSpanEvents(raw: unknown): SpanEvent[] {
  if (raw == null) return [];

  let items: unknown[];
  if (Array.isArray(raw)) {
    items = raw;
  } else if (typeof raw === "string") {
    if (raw === "[]") return [];
    // Fast boundary whitespace check with Unicode fallback for pasted/padded payloads.
    const firstChar = raw.at(0) ?? "";
    const lastChar = raw.at(-1) ?? "";
    const needsTrim =
      raw.charCodeAt(0) <= 32 ||
      raw.charCodeAt(raw.length - 1) <= 32 ||
      /\s/u.test(firstChar) ||
      /\s/u.test(lastChar);
    const trimmed = needsTrim ? raw.trim() : raw;
    if (trimmed === "[]") return [];
    if (!trimmed.startsWith("[") || !trimmed.endsWith("]")) return [];
    try {
      const parsed: unknown = JSON.parse(trimmed);
      if (!Array.isArray(parsed)) return [];
      items = parsed;
    } catch {
      return [];
    }
  } else {
    return [];
  }

  const events: SpanEvent[] = [];
  for (const item of items) {
    if (typeof item !== "object" || item === null) continue;
    const obj = item as Record<string, unknown>;
    const name = String(obj["name"] ?? "");
    const timestamp = String(obj["@timestamp"] ?? obj["timestamp"] ?? "");
    const attributes: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(obj)) {
      if (key !== "name" && key !== "@timestamp" && key !== "timestamp" && value != null) {
        attributes[key] = value;
      }
    }
    events.push({ name, timestamp, attributes });
  }
  return events;
}

/** Returns true if the column name belongs to the span links data */
function isSpanLinkColumn(colName: string): boolean {
  return (
    colName === "links.trace.id" ||
    colName === "links.span.id" ||
    colName.startsWith("links.attributes.")
  );
}

/**
 * Parse span links from a single ES|QL row.
 * Handles multi-value (array) fields for `links.trace.id` and `links.span.id`,
 * and zips them with any `links.attributes.*` columns.
 */
export function parseSpanLinks(colIndex: Map<string, number>, row: unknown[]): SpanLink[] {
  const getField = (field: string): unknown => {
    const idx = colIndex.get(field);
    return idx !== undefined ? row[idx] : null;
  };

  const rawTraceIds = getField("links.trace.id");
  const rawSpanIds = getField("links.span.id");

  if (rawTraceIds == null || rawSpanIds == null) return [];

  const traceIds = Array.isArray(rawTraceIds) ? rawTraceIds : [rawTraceIds];
  const spanIds = Array.isArray(rawSpanIds) ? rawSpanIds : [rawSpanIds];

  // Gather links.attributes.* columns sorted for deterministic order
  const attrCols: Array<[string, number]> = [];
  for (const [colName, idx] of colIndex) {
    if (colName.startsWith("links.attributes.")) {
      attrCols.push([colName, idx]);
    }
  }

  const count = Math.min(traceIds.length, spanIds.length);
  const links: SpanLink[] = [];

  for (let i = 0; i < count; i++) {
    if (traceIds[i] != null && spanIds[i] != null) {
      const attributes: Record<string, unknown> = {};
      for (const [colName, idx] of attrCols) {
        const rawVal = row[idx];
        const vals = Array.isArray(rawVal) ? rawVal : [rawVal];
        if (i < vals.length && vals[i] != null) {
          attributes[colName.slice("links.attributes.".length)] = vals[i];
        }
      }
      links.push({
        traceId: String(traceIds[i]),
        spanId: String(spanIds[i]),
        attributes,
      });
    }
  }

  return links;
}

/** Map a raw span status code to a user-facing display label. */
export function formatStatusLabel(status: string): string {
  if (status === "OK" || status === "STATUS_CODE_OK") return "Success";
  if (status === "STATUS_CODE_UNSET") return "Unset";
  return status;
}

/** Format a duration in microseconds to a human-readable string */
export function formatSpanDuration(durationUs: number): string {
  if (durationUs >= 1_000_000) {
    return `${(durationUs / 1_000_000).toFixed(durationUs >= 10_000_000 ? 0 : 1)}s`;
  }
  if (durationUs >= 1_000) {
    return `${(durationUs / 1_000).toFixed(durationUs >= 10_000 ? 0 : 1)}ms`;
  }
  return `${durationUs}µs`;
}

/**
 * Calculate trace-level timing info from a list of spans.
 */
export function getTraceTimeBounds(spans: Span[]): { startUs: number; endUs: number } {
  if (spans.length === 0) return { startUs: 0, endUs: 0 };
  let minStart = Infinity;
  let maxEnd = -Infinity;
  for (const span of spans) {
    const startUs = span.startTimeUs;
    const endUs = startUs + span.durationUs;
    if (startUs < minStart) minStart = startUs;
    if (endUs > maxEnd) maxEnd = endUs;
  }
  return { startUs: minStart, endUs: maxEnd };
}

/** User-facing summary for raw ES|QL / Elasticsearch parser errors. */
export function summarizeError(raw: string): string {
  if (/second argument of \[.*\] must be \[.*\]/i.test(raw) || /type mismatch/i.test(raw)) {
    return "A query type mismatch occurred. Results may still be usable.";
  }
  if (/verification_exception/i.test(raw) || /Found \d+ problem/i.test(raw)) {
    return "The query encountered a validation issue.";
  }
  if (/parsing_exception/i.test(raw)) {
    return "The query could not be parsed.";
  }
  return "A query error occurred.";
}
